using UnityEngine;
using System.Collections.Generic;

public class CameraRenderExample : MonoBehaviour
{
    public Camera myCamera;

    void Start()
    {
        // 确保摄像机挂载的游戏物体处于非激活状态
        myCamera.gameObject.SetActive(false);

        // 递归地激活所有祖先物体
        List<GameObject> ancestors = new List<GameObject>();
        GameObject current = myCamera.gameObject;
        while (current.transform.parent != null)
        {
            current = current.transform.parent.gameObject;
            ancestors.Add(current);
        }

        // 保存原始激活状态
        List<bool> originalActiveStates = new List<bool>();
        foreach (GameObject ancestor in ancestors)
        {
            originalActiveStates.Add(ancestor.activeSelf);
            ancestor.SetActive(true);
        }

        // 激活摄像机挂载的游戏物体
        myCamera.gameObject.SetActive(true);

        // 手动渲染摄像机
        myCamera.Render();

        // 恢复摄像机挂载的游戏物体的原始激活状态
        myCamera.gameObject.SetActive(false);

        // 恢复所有祖先物体的原始激活状态
        for (int i = 0; i < ancestors.Count; i++)
        {
            ancestors[i].SetActive(originalActiveStates[i]);
        }
    }
}
```

