using UnityEngine;

public class SmoothMovement : MonoBehaviour
{
    private Vector3 startPos;
    private Vector3 endPos;
    private float startTime;
    private const float duration = 0.4f;
    private bool isFirstPositionReceived = false;

    // 接收位置数据的方法
    public void ReceivePosition(Vector3 newPosition)
    {
        if (!isFirstPositionReceived)
        {
            // 第一次收到位置，设置起始位置为当前物体位置
            startPos = transform.position;
            endPos = newPosition;
            startTime = Time.time;
            isFirstPositionReceived = true;
        }
        else
        {
            // 不是第一次，设置起始位置为上一次的目标位置
            startPos = endPos;
            endPos = newPosition;
            startTime = Time.time;
        }
    }

    // Update函数中进行插值运动
    void Update()
    {
        if (isFirstPositionReceived)
        {
            float elapsed = Time.time - startTime;
            if (elapsed >= duration)
            {
                // 超过持续时间，直接设置为目标位置
                transform.position = endPos;
            }
            else
            {
                // 计算插值因子t
                float t = elapsed / duration;
                // 确保t在0到1之间
                t = Mathf.Clamp01(t);
                // 使用Lerp进行插值
                transform.position = Vector3.Lerp(startPos, endPos, t);
            }
        }
    }
}
