using UnityEngine;
using System.Collections.Generic;

public static class MaterialPropertyCopier
{
    public static void CopyProperties(Material source, Material destination)
    {
        if (source == null || destination == null)
        {
            Debug.LogError("Source or destination material is null.");
            return;
        }

        // 复制 Shader
        destination.shader = source.shader;

        // 获取所有属性名称
        List<string> propertyNames = new List<string>();
        source.GetPropertyNames(propertyNames);

        foreach (string propertyName in propertyNames)
        {
            MaterialPropertyType propertyType = GetPropertyType(source, propertyName);

            switch (propertyType)
            {
                case MaterialPropertyType.Color:
                    destination.SetColor(propertyName, source.GetColor(propertyName));
                    break;
                case MaterialPropertyType.Vector:
                    destination.SetVector(propertyName, source.GetVector(propertyName));
                    break;
                case MaterialPropertyType.Float:
                    destination.SetFloat(propertyName, source.GetFloat(propertyName));
                    break;
                case MaterialPropertyType.Texture:
                    destination.SetTexture(propertyName, source.GetTexture(propertyName));
                    break;
                default:
                    Debug.LogWarning($"Unsupported property type for {propertyName}.");
                    break;
            }
        }
    }

    private enum MaterialPropertyType
    {
        Color,
        Vector,
        Float,
        Texture
    }

    private static MaterialPropertyType GetPropertyType(Material material, string propertyName)
    {
        if (material.HasProperty(propertyName))
        {
            if (material.GetColor(propertyName) != Color.clear)
            {
