            }
            else if (material.GetVector(propertyName) != Vector4.zero)
            {
                return MaterialPropertyType.Vector;
            }
            else if (material.GetFloat(propertyName) != 0f)
            {
                return MaterialPropertyType.Float;
            }
            else if (material.GetTexture(propertyName) != null)
            {
                return MaterialPropertyType.Texture;
            }
        }

        return MaterialPropertyType.Float; // 默认返回 Float 类型
    }
}
