## 1. 二进制序列化与反序列化

二进制序列化适合需要高效存储和传输的场景，但可读性较差。

### 示例代码

```csharp
using System;
using System.IO;
using System.Runtime.Serialization.Formatters.Binary;
using UnityEngine;

[Serializable]
public class PlayerData
{
    public string name;
    public int level;
    public float health;
}

public class BinarySerializationExample : MonoBehaviour
{
    // 序列化对象到文件
    public void SerializeToFile(PlayerData data, string filePath)
    {
        try
        {
            BinaryFormatter formatter = new BinaryFormatter();
            using (FileStream stream = new FileStream(filePath, FileMode.Create))
            {
                formatter.Serialize(stream, data);
            }
            Debug.Log("Serialization successful: " + filePath);
        }
        catch (Exception e)
        {
            Debug.LogError("Serialization failed: " + e.Message);
        }
    }

    // 从文件反序列化对象
    public PlayerData DeserializeFromFile(string filePath)
    {
        if (!File.Exists(filePath))
        {
            Debug.LogError("File does not exist: " + filePath);
            return null;
        }

        try
        {
            BinaryFormatter formatter = new BinaryFormatter();
            using (FileStream stream = new FileStream(filePath, FileMode.Open))
            {
                PlayerData data = formatter.Deserialize(stream) as PlayerData;
                Debug.Log("Deserialization successful: " + filePath);
                return data;
            }
        }
        catch (Exception e)
        {
            Debug.LogError("Deserialization failed: " + e.Message);
            return null;
        }
    }

    // 示例用法
    void Start()
    {
        // 创建一个示例对象
        PlayerData player = new PlayerData
        {
            name = "Player1",
            level = 10,
            health = 80.5f
        };

        // 序列化到文件
        string filePath = Application.persistentDataPath + "/player.dat";
        SerializeToFile(player, filePath);

        // 从文件反序列化
        PlayerData loadedPlayer = DeserializeFromFile(filePath);
        if (loadedPlayer != null)
        {
            Debug.Log($"Loaded Player: Name={loadedPlayer.name}, Level={loadedPlayer.level}, Health={loadedPlayer.health}");
        }
    }
}
```

