在 Unity 中，你可以使用 `System.Diagnostics.Process` 类来执行 `.bat` 文件。以下是一个示例代码，展示了如何在 Unity 编辑器中创建一个方法，执行一段 `.bat` 命令。

```csharp
using UnityEditor;
using System.Diagnostics;

public class HMITools
{
    [MenuItem("HMI工具/更新ProtobufCs文件")]
    static void GenProtobufCsCode()
    {
        // 获取当前脚本所在的目录
        string scriptPath = System.IO.Path.GetDirectoryName(System.Reflection.Assembly.GetExecutingAssembly().Location);

        // 构建 .bat 文件的完整路径
        string batFilePath = System.IO.Path.Combine(scriptPath, "UpdateProtobufCs.bat");

        // 检查 .bat 文件是否存在
        if (System.IO.File.Exists(batFilePath))
        {
            // 创建一个新的 Process 实例
            ProcessStartInfo processStartInfo = new ProcessStartInfo(batFilePath);
            processStartInfo.WindowStyle = ProcessWindowStyle.Hidden;
            processStartInfo.CreateNoWindow = true;
            processStartInfo.UseShellExecute = false;
            processStartInfo.RedirectStandardOutput = true;
            processStartInfo.RedirectStandardError = true;

            // 启动进程
            Process process = Process.Start(processStartInfo);

            // 读取输出和错误信息
            string output = process.StandardOutput.ReadToEnd();
            string error = process.StandardError.ReadToEnd();

            // 等待进程完成
            process.WaitForExit();

            // 输出结果
            UnityEngine.Debug.Log("Bat 文件执行完成");
            if (!string.IsNullOrEmpty(output))
            {
                UnityEngine.Debug.Log("输出: " + output);
            }
            if (!string.IsNullOrEmpty(error))
            {
                UnityEngine.Debug.LogError("错误: " + error);
            }
        }
        else
        {
            UnityEngine.Debug.LogError("Bat 文件不存在: " + batFilePath);
        }
    }
}
```

