ViewGroup parent = (ViewGroup) itemView.getParent();
if (parent != null) {
    parent.removeView(itemView);
}

// 第二次使用（复用同一个 View）
TextView textView2 = itemView.findViewById(R.id.text_view);
textView2.setText("Content 2");

// 再次添加到父布局
parent.addView(itemView);
```

