using System;
using System.Collections.Generic;
using System.IO;
using UnityEngine;

public class FrameDataLogger : MonoBehaviour
{
    private bool isLogging = true; // 是否记录数据
    private List<SByte> frameDataCache = new List<SByte>(); // 缓存每一帧的数据
    private string filePath; // 文件路径

    private void Start()
    {
        // 初始化文件路径
        filePath = Path.Combine(Application.persistentDataPath, "FrameData.txt");
        Debug.Log("数据文件路径: " + filePath);
    }

