    {
        if (isLogging)
        {
            // 模拟获取每一帧的数据
            SByte[] frameData = GetFrameData();

            // 将数据添加到缓存中
            frameDataCache.AddRange(frameData);

            // 如果缓存数据量较大，可以写入文件并清空缓存
            if (frameDataCache.Count > 1000) // 每 1000 个数据写入一次文件
            {
                WriteDataToFile(frameDataCache);
                frameDataCache.Clear();
            }
        }
    }

    private void OnDestroy()
    {
        // 游戏对象销毁时，将剩余的数据写入文件
        if (frameDataCache.Count > 0)
        {
            WriteDataToFile(frameDataCache);
            frameDataCache.Clear();
        }
    }

    // 模拟获取每一帧的数据
    private SByte[] GetFrameData()
    {
        // 这里替换为实际获取数据的逻辑
        return new SByte[] { 1, -2, 3, -4, 5 };
    }

    // 将数据写入文件
    private void WriteDataToFile(List<SByte> data)
    {
        try
        {
            using (FileStream fs = new FileStream(filePath, FileMode.Append)) // 使用追加模式
            using (BinaryWriter bw = new BinaryWriter(fs))
            {
                foreach (SByte b in data)
                {
                    bw.Write(b);
                }
            }

            Debug.Log("数据写入文件成功，当前文件大小: " + new FileInfo(filePath).Length + " 字节");
        }
        catch (Exception e)
        {
            Debug.LogError("数据写入文件失败: " + e.Message);
        }
    }
}
