#### 示例：添加发光效果
```glsl
void main() {
    vec4 texColor = texture2D(u_texture, v_texCoord0);
    vec3 glowColor = vec3(1.0, 0.8, 0.2); // 发光颜色
    float glowIntensity = 0.5; // 发光强度
    vec3 finalColor = texColor.rgb + glowColor * glowIntensity;
    gl_FragColor = vec4(finalColor, texColor.a);
}
```

#### 示例：添加模糊效果
```glsl
uniform float u_blurRadius; // 模糊半径

void main() {
    vec4 color = vec4(0.0);
    int samples = 10; // 采样次数
    for (int i = 0; i < samples; i++) {
        vec2 offset = vec2(float(i) / float(samples) - 0.5) * u_blurRadius;
        color += texture2D(u_texture, v_texCoord0 + offset);
    }
    gl_FragColor = color / float(samples);
}
```

