```java
public class ShaderParticleExample extends ApplicationAdapter {
    private ParticleEffect particleEffect;
    private SpriteBatch batch;
    private ShaderProgram shader;

    @Override
    public void create() {
        // 加载 Shader
        shader = new ShaderProgram(
            Gdx.files.internal("shaders/particle.vert"),
            Gdx.files.internal("shaders/particle.frag")
        );

        if (!shader.isCompiled()) {
            Gdx.app.error("Shader", "Compilation failed: " + shader.getLog());
        }

        // 加载粒子效果
        particleEffect = new ParticleEffect();
        particleEffect.load(Gdx.files.internal("your-particle-effect.p"), Gdx.files.internal(""));
        particleEffect.setPosition(Gdx.graphics.getWidth() / 2, Gdx.graphics.getHeight() / 2);
        particleEffect.start();

        batch = new SpriteBatch();
    }

    @Override
    public void render() {
        Gdx.gl.glClear(GL20.GL_COLOR_BUFFER_BIT);

        // 更新粒子效果
        particleEffect.update(Gdx.graphics.getDeltaTime());

        // 启用自定义 Shader
        batch.setShader(shader);

        // 渲染粒子效果
        batch.begin();
        particleEffect.draw(batch);
        batch.end();

        // 恢复默认 Shader
        batch.setShader(null);
    }

    @Override
    public void dispose() {
        particleEffect.dispose();
        batch.dispose();
        shader.dispose();
    }
}
