### 实现一个基于 WebGL 的粒子动画，满足以下要求：

1. **黑色背景**：设置画布的清除颜色为黑色。
2. **从远处发射长条光束**：通过发射粒子束模拟光束效果。
3. **分散到摄像机周围**：粒子从远处向摄像机位置移动并扩散。
4. **拖影效果**：使用混合模式和透明度实现拖影。
5. **颜色变化和渐变**：随着时间变化更新粒子颜色，实现渐变效果。

### 代码实现：

```html
<!DOCTYPE html>
<html>
<head>
    <title>WebGL Particle Animation</title>
    <style>
        body { margin: 0; overflow: hidden; }
        canvas { display: block; }
    </style>
</head>
<body>
<canvas id="canvas"></canvas>
<script>
    // 初始化 WebGL
    var canvas = document.getElementById('canvas');
    var gl = canvas.getContext('webgl') || canvas.getContext('experimental-webgl');
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;

    // 顶点着色器代码
    var vsSource = `
        attribute vec3 aPosition;
        attribute vec4 aColor;
        varying vec4 vColor;
        uniform mat4 uModelViewMatrix;
        uniform mat4 uProjectionMatrix;
        void main() {
            gl_Position = uProjectionMatrix * uModelViewMatrix * vec4(aPosition, 1.0);
            vColor = aColor;
        }
    `;

    // 片元着色器代码
    var fsSource = `
        precision mediump float;
        varying vec4 vColor;
        void main() {
            gl_FragColor = vColor;
        }
    `;

    // 创建着色器程序
    function createShader(gl, type, source) {
        var shader = gl.createShader(type);
        gl.shaderSource(shader, source);
        gl.compileShader(shader);
        if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
            console.error(gl.getShaderInfoLog(shader));
            return null;
        }
        return shader;
    }

    var vertexShader = createShader(gl, gl.VERTEX_SHADER, vsSource);
    var fragmentShader = createShader(gl, gl.FRAGMENT_SHADER, fsSource);
    var program = gl.createProgram();
    gl.attachShader(program, vertexShader);
    gl.attachShader(program, fragmentShader);
    gl.linkProgram(program);
    if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
        console.error(gl.getProgramInfoLog(program));
        return;
    }
    gl.useProgram(program);

    // 定义粒子数据
    var particleCount = 10000;
    var positionData = new Float32Array(particleCount * 3);
    var colorData = new Float32Array(particleCount * 4);

    // 创建缓冲区
    var positionBuffer = gl.createBuffer();
    gl.bindBuffer(gl.ARRAY_BUFFER, positionBuffer);
    gl.bufferData(gl.ARRAY_BUFFER, positionData, gl.DYNAMIC_DRAW);

    var colorBuffer = gl.createBuffer();
    gl.bindBuffer(gl.ARRAY_BUFFER, colorBuffer);
    gl.bufferData(gl.ARRAY_BUFFER, colorData, gl.DYNAMIC_DRAW);

    // 获取属性位置
    var aPosition = gl.getAttribLocation(program, 'aPosition');
    var aColor = gl.getAttribLocation(program, 'aColor');

    gl.enableVertexAttribArray(aPosition);
    gl.vertexAttribPointer(aPosition, 3, gl.FLOAT, false, 0, 0);

    gl.enableVertexAttribArray(aColor);
    gl.vertexAttribPointer(aColor, 4, gl.FLOAT, false, 0, 0);

    // 设置 uniforms
    var uModelViewMatrix = gl.getUniformLocation(program, 'uModelViewMatrix');
    var uProjectionMatrix = gl.getUniformLocation(program, 'uProjectionMatrix');

    // 相机设置
    var cameraPosition = [0, 0, 1];
    var target = [0, 0, 0];
    var up = [0, 1, 0];
    var viewMatrix = mat4.lookAt(mat4.create(), cameraPosition, target, up);

    var projectionMatrix = mat4.perspective(mat4.create(), glMatrix.toRadian(60), canvas.width / canvas.height, 0.1, 1000.0);

    gl.uniformMatrix4fv(uModelViewMatrix, false, viewMatrix);
    gl.uniformMatrix4fv(uProjectionMatrix, false, projectionMatrix);

    // 粒子系统
    var particles = [];
    for (var i = 0; i < particleCount; i++) {
        var particle = {
            position: [0, 0, 10],
            velocity: [Math.random() * 0.1 - 0.05, Math.random() * 0.1 - 0.05, -Math.random() * 5 - 5],
            color: [Math.random(), Math.random(), Math.random(), 1.0],
            age: 0.0,
            lifespan: 1.0 + Math.random() * 2.0
        };
        particles.push(particle);
    }

    // 渲染循环
    function render() {
        gl.clearColor(0.0, 0.0, 0.0, 1.0);
        gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);

        gl.blendFunc(gl.SRC_ALPHA, gl.ONE);
        gl.enable(gl.BLEND);

        var time = performance.now() / 1000.0;

        // 更新粒子
        for (var i = 0; i < particleCount; i++) {
            var particle = particles[i];
            particle.position[0] += particle.velocity[0];
            particle.position[1] += particle.velocity[1];
            particle.position[2] += particle.velocity[2];
            particle.age += 0.016; // 假设16ms一帧

            if (particle.age > particle.lifespan) {
                // 重置粒子
                particle.position = [0, 0, 10];
                particle.velocity = [Math.random() * 0.1 - 0.05, Math.random() * 0.1 - 0.05, -Math.random() * 5 - 5];
                particle.age = 0.0;
                particle.color = [Math.random(), Math.random(), Math.random(), 1.0];
                particle.lifespan = 1.0 + Math.random() * 2.0;
            }

            // 计算颜色衰减
            var alpha = 1.0 - (particle.age / particle.lifespan);
            particle.color[3] = alpha;

            // 写入缓冲区
            positionData[i * 3] = particle.position[0];
            positionData[i * 3 + 1] = particle.position[1];
            positionData[i * 3 + 2] = particle.position[2];
            colorData[i * 4] = particle.color[0];
            colorData[i * 4 + 1] = particle.color[1];
            colorData[i * 4 + 2] = particle.color[2];
            colorData[i * 4 + 3] = particle.color[3];
        }

        gl.bindBuffer(gl.ARRAY_BUFFER, positionBuffer);
        gl.bufferSubData(gl.ARRAY_BUFFER, 0, positionData);

        gl.bindBuffer(gl.ARRAY_BUFFER, colorBuffer);
        gl.bufferSubData(gl.ARRAY_BUFFER, 0, colorData);

        gl.drawArrays(gl.POINTS, 0, particleCount);

        requestAnimationFrame(render);
    }

    render();

    // 事件监听窗口调整
    window.addEventListener('resize', function() {
        canvas.width = window.innerWidth;
        canvas.height = window.innerHeight;
        gl.viewport(0, 0, canvas.width, canvas.height);
        projectionMatrix = mat4.perspective(mat4.create(), glMatrix.toRadian(60), canvas.width / canvas.height, 0.1, 1000.0);
        gl.uniformMatrix4fv(uProjectionMatrix, false, projectionMatrix);
    });
</script>
</body>
</html>
```

### 说明：

1. **黑色背景**：通过 `gl.clearColor(0.0, 0.0, 0.0, 1.0);` 设置背景颜色为黑色。
2. **发射长条光束**：粒子从远处（Z轴正方向）发射，形成光束效果。
3. **分散到摄像机周围**：粒子带有随机的X和Y速度，使它们向摄像机位置扩散。
4. **拖影效果**：使用 `gl.blendFunc(gl.SRC_ALPHA, gl.ONE);` 和粒子透明度变化实现拖影。
5. **颜色变化和渐变**：粒子颜色在生命周期内线性变化，产生渐变效果。

### 依赖库：

