```csharp
using UnityEngine;

public class MultiPlayerTouchInput : MonoBehaviour
{
    private const string TAG = "MultiPlayerTouchInput";

    private void Update()
    {
        // 获取所有触摸点
        Touch[] touches = Input.touches;

        // 遍历所有触摸点
        foreach (Touch touch in touches)
        {
            int fingerId = touch.fingerId; // 触摸点唯一标识符
            Vector2 touchPosition = touch.position; // 触摸点位置
            int displayIndex = touch.displayIndex; // 触摸点所属的显示器索引
            TouchPhase touchPhase = touch.phase; // 触摸点状态
            Vector2 touchDelta = touch.deltaPosition; // 触摸点移动增量

            // 打印触摸点信息
            Debug.Log($"Touch Info - " +
                      $"Finger ID: {fingerId}, " +
                      $"Position: {touchPosition}, " +
                      $"Display Index: {displayIndex}, " +
                      $"Phase: {touchPhase}, " +
                      $"Delta: {touchDelta}, " +
                      $"Touches Count: {touches.Length}");

            // 根据 displayIndex 区分玩家
            if (displayIndex == 0)
            {
                HandlePlayer1Touch(fingerId, touchPosition, touchPhase, touchDelta);
            }
            else if (displayIndex == 1)
            {
                HandlePlayer2Touch(fingerId, touchPosition, touchPhase, touchDelta);
            }
        }
    }

    // 处理玩家1的触摸输入
    private void HandlePlayer1Touch(int fingerId, Vector2 position, TouchPhase phase, Vector2 delta)
    {
        // 实现玩家1的多指触摸逻辑
        Debug.Log($"Player 1 - Finger ID: {fingerId}, Position: {position}, Phase: {phase}, Delta: {delta}");
    }

    // 处理玩家2的触摸输入
    private void HandlePlayer2Touch(int fingerId, Vector2 position, TouchPhase phase, Vector2 delta)
    {
        // 实现玩家2的多指触摸逻辑
        Debug.Log($"Player 2 - Finger ID: {fingerId}, Position: {position}, Phase: {phase}, Delta: {delta}");
    }
}
