### 1. **使用字典存储多个玩家的触摸输入**
   - 使用 `Dictionary<int, List<Touch>>` 存储每个玩家的触摸输入，其中 `key` 是玩家的 `index`，`value` 是该玩家的触摸点列表。

#### **修改后的代码**
```csharp
using UnityEngine;
using System.Collections.Generic;

public class MultiPlayerTouchInput : MonoBehaviour
{
    // 单例实例
    public static MultiPlayerTouchInput Instance { get; private set; }

    // 存储多个玩家的触摸输入
    public Dictionary<int, List<Touch>> PlayerTouches { get; private set; } = new Dictionary<int, List<Touch>>();

    private void Awake()
    {
        // 初始化单例
        if (Instance == null)
        {
            Instance = this;
        }
        else
        {
            Destroy(gameObject);
        }
    }

    private void Update()
    {
        // 清空上一帧的触摸点
        foreach (var playerTouches in PlayerTouches.Values)
        {
            playerTouches.Clear();
        }

        // 获取所有触摸点
        Touch[] touches = Input.touches;

        // 遍历所有触摸点
        foreach (Touch touch in touches)
        {
            int displayIndex = touch.displayIndex;

            // 根据 displayIndex 区分玩家
            if (!PlayerTouches.ContainsKey(displayIndex))
            {
                PlayerTouches[displayIndex] = new List<Touch>();
            }

            // 存储玩家的触摸点
            PlayerTouches[displayIndex].Add(touch);
        }
    }

    // 获取指定玩家的触摸输入
    public List<Touch> GetPlayerTouches(int playerIndex)
    {
        if (PlayerTouches.ContainsKey(playerIndex))
        {
            return PlayerTouches[playerIndex];
        }
        return new List<Touch>(); // 如果玩家不存在，返回空列表
    }
}
```

