        if (Instance == null)
        {
            Instance = this;
        }
        else
        {
            Destroy(gameObject);
        }

        // 初始化玩家触摸输入列表
        for (int i = 0; i < 2; i++) // 假设最多支持 2 个玩家
        {
            PlayerTouches.Add(new List<Touch>());
        }
    }

    private void Update()
    {
        // 清空上一帧的触摸点
        foreach (var playerTouches in PlayerTouches)
        {
            playerTouches.Clear();
        }

        // 获取所有触摸点
        Touch[] touches = Input.touches;

        // 遍历所有触摸点
        foreach (Touch touch in touches)
        {
            int displayIndex = touch.displayIndex;

            // 根据 displayIndex 区分玩家
            if (displayIndex >= 0 && displayIndex < PlayerTouches.Count)
            {
                PlayerTouches[displayIndex].Add(touch); // 存储玩家的触摸点
            }
        }
    }

    // 获取指定玩家的触摸输入
