using UnityEngine;
using UnityEngine.InputSystem;
using System.Collections.Generic;

public class MouseInputHandler : MonoBehaviour
{
    // 存储鼠标输入事件
    public Dictionary<int, List<Vector2>> MouseInputs { get; private set; } = new Dictionary<int, List<Vector2>>();

    private void Update()
    {
        // 清空上一帧的鼠标输入
        foreach (var mouseInputs in MouseInputs.Values)
        {
            mouseInputs.Clear();
        }

        // 获取鼠标位置
        var mouse = Mouse.current;
        if (mouse == null) return;

        Vector2 mousePosition = mouse.position.ReadValue();

        // 根据鼠标位置分配 displayIndex
        int displayIndex = mousePosition.x < 2560 ? 0 : 10;

        // 初始化 displayIndex 对应的列表
        if (!MouseInputs.ContainsKey(displayIndex))
        {
            MouseInputs[displayIndex] = new List<Vector2>();
        }

        // 存储鼠标输入事件
        MouseInputs[displayIndex].Add(mousePosition);

        // 打印调试信息
        Debug.Log($"Mouse Position: {mousePosition}, Display Index: {displayIndex}");
    }

    // 获取指定 displayIndex 的鼠标输入事件
    public List<Vector2> GetMouseInputs(int displayIndex)
    {
        if (MouseInputs.ContainsKey(displayIndex))
        {
            return MouseInputs[displayIndex];
        }
        return new List<Vector2>(); // 如果 displayIndex 不存在，返回空列表
    }
}
```

