        public bool middleButton; // 中键状态
        public Vector2 scrollDelta; // 滚轮状态

        public MouseData(Vector2 position, bool leftButton, bool rightButton, bool middleButton, Vector2 scrollDelta)
        {
            this.position = position;
            this.leftButton = leftButton;
            this.rightButton = rightButton;
            this.middleButton = middleButton;
            this.scrollDelta = scrollDelta;
        }
    }

    // 存储鼠标输入事件
    public Dictionary<int, List<MouseData>> MouseInputs { get; private set; } = new Dictionary<int, List<MouseData>>();

    private void Awake()
    {
        // 初始化单例
        if (Instance == null)
        {
            Instance = this;
        }
        else
        {
            Destroy(gameObject);
        }
    }

    private void Update()
    {
        UpdateMouse();
    }

    public static void UpdateMouse()
    {
        // 清空上一帧的鼠标输入
        foreach (var mouseInputs in Instance.MouseInputs.Values)
        {
            mouseInputs.Clear();
        }

        // 获取鼠标相关属性
        Vector2 mousePosition = Input.mousePosition;
        bool leftButton = Input.GetMouseButton(0); // 左键状态
        bool rightButton = Input.GetMouseButton(1); // 右键状态
        bool middleButton = Input.GetMouseButton(2); // 中键状态
        Vector2 scrollDelta = Input.mouseScrollDelta; // 滚轮状态

        // 根据鼠标位置分配 displayIndex
        int displayIndex = mousePosition.x < 2560 ? 0 : 10;

        // 初始化 displayIndex 对应的列表
        if (!Instance.MouseInputs.ContainsKey(displayIndex))
        {
            Instance.MouseInputs[displayIndex] = new List<MouseData>();
        }

        // 创建 MouseData 对象
        MouseData mouseData = new MouseData(mousePosition, leftButton, rightButton, middleButton, scrollDelta);

        // 存储鼠标输入事件
        Instance.MouseInputs[displayIndex].Add(mouseData);

        // 打印调试信息
        Debug.Log($"Mouse Data - Display Index: {displayIndex}, Position: {mouseData.position}, " +
                  $"Left Button: {mouseData.leftButton}, Right Button: {mouseData.rightButton}, " +
                  $"Middle Button: {mouseData.middleButton}, Scroll Delta: {mouseData.scrollDelta}");
    }

    // 获取指定 displayIndex 的鼠标输入事件
    public List<MouseData> GetMouseInputs(int displayIndex)
    {
        if (MouseInputs.ContainsKey(displayIndex))
        {
            return MouseInputs[displayIndex];
        }
        return new List<MouseData>(); // 如果 displayIndex 不存在，返回空列表
    }
}
```

---

### 5. **代码说明**

#### **1. `MouseData` 内部类**
   - 封装了鼠标的相关属性：
     - `position`：鼠标位置。
     - `leftButton`：左键状态（是否按下）。
     - `rightButton`：右键状态（是否按下）。
     - `middleButton`：中键状态（是否按下）。
     - `scrollDelta`：滚轮状态（滚动的增量）。

#### **2. `MouseInputs` 数据结构**
   - 使用 `Dictionary<int, List<MouseData>>` 存储不同 `displayIndex` 的鼠标输入事件。
   - `displayIndex` 是屏幕区域的标识符（例如 `0` 表示左边屏幕，`10` 表示右边屏幕）。

#### **3. `UpdateMouse` 方法**
   - 清空上一帧的鼠标输入。
   - 获取鼠标的相关属性（位置、按钮状态、滚轮状态）。
   - 根据鼠标位置分配 `displayIndex`。
   - 创建 `MouseData` 对象并存储到 `MouseInputs` 中。

#### **4. `GetMouseInputs` 方法**
   - 获取指定 `displayIndex` 的鼠标输入事件。

---

### 6. **使用示例**
   - 在其他脚本中，可以通过 `MouseInputHandler.Instance.GetMouseInputs(displayIndex)` 获取指定 `displayIndex` 的鼠标输入事件。

