// 帧率控制系统
public class FrameRateController : MonoBehaviour
{
    [Header("逻辑帧率设置")]
    [SerializeField] private float logicFrameRate = 20f;  // 逻辑更新频率（消息线程）

    [Header("渲染帧率设置")] 
