            currentRenderFPS = Mathf.Clamp((int)(1f / Time.smoothDeltaTime), minRenderFPS, maxRenderFPS);
            Application.targetFrameRate = currentRenderFPS;
        }
    }

    // 独立逻辑更新循环
    IEnumerator LogicUpdateLoop()
    {
        while(true)
        {
            // 执行核心逻辑更新
            ExecuteLogicFrame();

            // 精确等待逻辑帧间隔
            yield return new WaitForSecondsRealtime(logicInterval);
        }
    }

    // 定时逻辑帧更新
    private void ExecuteLogicFrame()
    {
        // 在此处处理：
