// 数据解析器
public class RadarDataParser : MonoBehaviour
{
    public byte[] rawData; // 来自雷达的原始数据

    public List<RadarPoint> ParsePointCloud()
    {
        List<RadarPoint> points = new List<RadarPoint>();

        // 示例解析逻辑（需根据实际协议实现）
        using (MemoryStream ms = new MemoryStream(rawData))
        using (BinaryReader br = new BinaryReader(ms))
        {
            while (ms.Position < ms.Length)
            {
                RadarPoint point = new RadarPoint
                {
                    position = new Vector3(
                        br.ReadSingle(),  // X
                        br.ReadSingle(),  // Y 
                        br.ReadSingle()), // Z
                    intensity = br.ReadSingle(),
                    velocity = br.ReadSingle()
                };
                points.Add(point);
            }
        }

        return points;
    }
}
