#### **2. 坐标系转换**
```csharp
// 雷达坐标系到Unity世界坐标的转换
public static class CoordinateConverter
{
    // 雷达安装参数（示例值）
    private static readonly Vector3 radarPosition = new Vector3(0, 0.5f, 0);
    private static readonly Quaternion radarRotation = Quaternion.Euler(0, 180, 0);

    public static Vector3 ConvertToWorld(Vector3 localPoint)
    {
        // 坐标轴转换（雷达坐标系通常为右前上）
        Vector3 unityLocal = new Vector3(
            localPoint.z,  // Unity Y轴对应雷达Z轴（高度）
            localPoint.x,  // Unity Z轴对应雷达X轴（前进方向）
            localPoint.y   // Unity X轴对应雷达Y轴（横向）
        );

        return radarPosition + radarRotation * unityLocal;
    }
}
```

