```csharp
public class PointCloudRenderer : MonoBehaviour
{
    public Material pointMaterial;
    public float pointSize = 0.1f;

    private ComputeBuffer pointBuffer;
    private List<Vector4> pointData = new List<Vector4>();

    void OnRenderObject()
    {
        pointMaterial.SetPass(0);
        pointMaterial.SetBuffer("_PointBuffer", pointBuffer);
        pointMaterial.SetFloat("_PointSize", pointSize);

        Graphics.DrawProceduralNow(MeshTopology.Points, pointData.Count);
    }

    public void UpdatePoints(List<RadarPoint> points)
    {
        pointData.Clear();
        foreach (var p in points)
        {
            Vector3 worldPos = CoordinateConverter.ConvertToWorld(p.position);
            pointData.Add(new Vector4(
                worldPos.x, 
                worldPos.y,
                worldPos.z,
                p.intensity // 将强度值存入w分量
            ));
        }

        if(pointBuffer != null) pointBuffer.Release();
        pointBuffer = new ComputeBuffer(pointData.Count, sizeof(float)*4);
        pointBuffer.SetData(pointData);
    }

    void OnDestroy()
    {
        pointBuffer?.Release();
    }
}
