#### **4. 点云着色器（ShaderLab）**
```shader
Shader "Custom/PointCloud" {
    Properties {
        _PointSize ("Point Size", Range(0.01, 0.5)) = 0.1
    }

    SubShader {
        Tags { "RenderType"="Opaque" }

        Pass {
            CGPROGRAM
            #pragma vertex vert
            #pragma fragment frag
            #pragma target 4.5

            #include "UnityCG.cginc"

            StructuredBuffer<float4> _PointBuffer;
            float _PointSize;

            struct v2f {
                float4 pos : SV_POSITION;
                float intensity : TEXCOORD0;
            };

            v2f vert(uint id : SV_VertexID)
            {
                float4 data = _PointBuffer[id];
                float4 worldPos = float4(data.xyz, 1.0);
                float4 clipPos = UnityWorldToClipPos(worldPos);

                // 点尺寸调整
                clipPos.w += _PointSize * (1.0 - saturate(length(data.xyz - _WorldSpaceCameraPos) / 100.0));

                v2f o;
                o.pos = clipPos;
                o.intensity = data.w;
                return o;
            }

            fixed4 frag(v2f i) : SV_Target
            {
                // 根据强度值着色（示例：红→黄渐变）
                float3 color = lerp(float3(1,0,0), float3(1,1,0), i.intensity);
                return fixed4(color, 1);
            }
            ENDCG
        }
    }
}
