#### **5. 模型重建（Marching Cubes示例）**
```csharp
public class SurfaceReconstructor : MonoBehaviour
{
    public int gridResolution = 50;
    public float isoLevel = 0.5f;

    private float[,,] densityGrid;

    public Mesh BuildMesh(List<RadarPoint> points)
    {
        InitializeDensityGrid(points);

        MarchingCubes mc = new MarchingCubes();
        mc.Generate(densityGrid, isoLevel);

        Mesh mesh = new Mesh();
        mesh.vertices = mc.Vertices.ToArray();
        mesh.triangles = mc.Triangles.ToArray();
        mesh.RecalculateNormals();

        return mesh;
    }

    private void InitializeDensityGrid(List<RadarPoint> points)
    {
        densityGrid = new float[gridResolution, gridResolution, gridResolution];

        // 基于点云生成密度场（示例：高斯分布）
        foreach (var p in points)
        {
            Vector3Int gridPos = WorldToGrid(p.position);
            for(int x=-2; x<=2; x++)
            for(int y=-2; y<=2; y++)
            for(int z=-2; z<=2; z++)
            {
                Vector3Int idx = gridPos + new Vector3Int(x,y,z);
                if(IsInGrid(idx))
                {
                    float dist = Vector3.Distance(gridPos, idx);
                    densityGrid[idx.x, idx.y, idx.z] += Mathf.Exp(-dist*dist);
                }
            }
        }
    }

    private Vector3Int WorldToGrid(Vector3 pos)
    {
        // 坐标映射到网格空间
        return new Vector3Int(
            Mathf.FloorToInt(pos.x * gridResolution),
            Mathf.FloorToInt(pos.y * gridResolution),
            Mathf.FloorToInt(pos.z * gridResolution)
        );
    }

    private bool IsInGrid(Vector3Int idx)
    {
        return idx.x >= 0 && idx.x < gridResolution &&
               idx.y >= 0 && idx.y < gridResolution &&
               idx.z >= 0 && idx.z < gridResolution;
    }
}
