#### **2. Marching Cubes改进版（适合密集点云）**
```csharp
public class AdvancedMarchingCubes : MonoBehaviour
{
    public float isoLevel = 0.5f;
    public Vector3Int gridSize = new Vector3Int(32, 32, 32);

    private float[,,] densityGrid;

    public Mesh BuildMesh(List<Vector3> points)
    {
        InitializeDensityGrid(points);
        return March();
    }

    private void InitializeDensityGrid(List<Vector3> points)
    {
        densityGrid = new float[gridSize.x, gridSize.y, gridSize.z];

        // 并行化密度计算（使用Job System）
        NativeArray<Vector3> nativePoints = new NativeArray<Vector3>(points.ToArray(), Allocator.TempJob);

        var job = new DensityCalculationJob
        {
            points = nativePoints,
            gridSize = gridSize,
            densityGrid = new NativeArray<float>(gridSize.x * gridSize.y * gridSize.z, Allocator.TempJob)
        };

        JobHandle handle = job.Schedule();
        handle.Complete();

        // 转换回多维数组
        for(int x=0; x<gridSize.x; x++)
        for(int y=0; y<gridSize.y; y++)
        for(int z=0; z<gridSize.z; z++)
        {
            int index = x + y * gridSize.x + z * gridSize.x * gridSize.y;
            densityGrid[x,y,z] = job.densityGrid[index];
        }

        nativePoints.Dispose();
        job.densityGrid.Dispose();
    }

    [BurstCompile]
    struct DensityCalculationJob : IJob
    {
        [ReadOnly] public NativeArray<Vector3> points;
        public Vector3Int gridSize;
        public NativeArray<float> densityGrid;

        public void Execute()
        {
            // 基于RBF核函数的密度计算
            for(int i=0; i<points.Length; i++)
            {
                Vector3 p = points[i];
                Vector3Int gridPos = new Vector3Int(
                    Mathf.FloorToInt(p.x * gridSize.x),
                    Mathf.FloorToInt(p.y * gridSize.y),
                    Mathf.FloorToInt(p.z * gridSize.z)
                );

                // 影响周围8个网格
                for(int dx=-1; dx<=1; dx++)
                for(int dy=-1; dy<=1; dy++)
                for(int dz=-1; dz<=1; dz++)
                {
                    Vector3Int idx = gridPos + new Vector3Int(dx, dy, dz);
                    if(IsValidIndex(idx))
                    {
                        float dist = Vector3.Distance(p, GridToWorld(idx));
                        int linearIndex = idx.x + idx.y * gridSize.x + idx.z * gridSize.x * gridSize.y;
                        densityGrid[linearIndex] += Mathf.Exp(-dist * dist * 10f);
                    }
                }
            }
        }

        private bool IsValidIndex(Vector3Int idx)
        {
            return idx.x >=0 && idx.x < gridSize.x &&
                   idx.y >=0 && idx.y < gridSize.y &&
                   idx.z >=0 && idx.z < gridSize.z;
        }

        private Vector3 GridToWorld(Vector3Int idx)
        {
            return new Vector3(
                idx.x / (float)gridSize.x,
                idx.y / (float)gridSize.y,
                idx.z / (float)gridSize.z
            );
        }
    }
}
```

