using UnityEngine;
using System.Collections.Generic;
using Earcut; // 假设有这个命名空间

public class RoadGenerator : MonoBehaviour
{
    public Material drivingMaterial;
    public Material nonDrivingMaterial;

    public void GenerateRoad(List<Vector3> points, int color)
    {
        GameObject roadSegment = new GameObject("RoadSegment");
        MeshFilter meshFilter = roadSegment.AddComponent<MeshFilter>();
        MeshRenderer meshRenderer = roadSegment.AddComponent<MeshRenderer>();

        Mesh mesh = new Mesh();

        // 投影到XZ平面，转换为二维坐标
        List<Vector2> points2D = new List<Vector2>();
        foreach (Vector3 p in points)
        {
            points2D.Add(new Vector2(p.x, p.z));
        }

        // 使用Earcut进行三角剖分
        int[] triangles = EarcutNet.Earcut.Tessellate(points2D, null);

        // 转换回三维顶点，假设Y坐标为0
        Vector3[] vertices = new Vector3[points.Count];
        for (int i = 0; i < points.Count; i++)
        {
            vertices[i] = new Vector3(points2D[i].x, 0, points2D[i].y);
        }

        mesh.vertices = vertices;
        mesh.triangles = triangles;
        mesh.RecalculateNormals();

        meshFilter.mesh = mesh;
        meshRenderer.material = (color == 0x1) ? drivingMaterial : nonDrivingMaterial;
    }
}

