```csharp
using UnityEngine;

[RequireComponent(typeof(MeshFilter), typeof(MeshRenderer))]
public class ConvexPolygonDrawer : MonoBehaviour
{
    public Vector2[] polygonVertices; // 输入二维顶点（XZ平面）
    public Material meshMaterial;     // 面材质

    void Start()
    {
        CreateMeshFromPolygon();
    }

    void CreateMeshFromPolygon()
    {
        // 确保顶点数量足够构成多边形
        if (polygonVertices == null || polygonVertices.Length < 3)
        {
            Debug.LogError("至少需要3个顶点来构成多边形。");
            return;
        }

        // 将Vector2转换为Vector3（XZ平面）
        Vector3[] vertices3D = new Vector3[polygonVertices.Length];
        for (int i = 0; i < polygonVertices.Length; i++)
        {
            vertices3D[i] = new Vector3(polygonVertices[i].x, 0, polygonVertices[i].y);
        }

        // 生成三角形索引（凸多边形三角剖分）
        int[] triangles = new int[(polygonVertices.Length - 2) * 3];
        int triangleIndex = 0;
        for (int i = 1; i < polygonVertices.Length - 1; i++)
        {
            triangles[triangleIndex++] = 0;
            triangles[triangleIndex++] = i;
            triangles[triangleIndex++] = i + 1;
        }

        // 创建Mesh
        Mesh mesh = new Mesh();
        mesh.vertices = vertices3D;
        mesh.triangles = triangles;

        // 自动计算法线（确保双面可见）
        mesh.RecalculateNormals();

        // 应用Mesh到组件
        MeshFilter meshFilter = GetComponent<MeshFilter>();
        meshFilter.mesh = mesh;

        // 设置材质
        MeshRenderer meshRenderer = GetComponent<MeshRenderer>();
        meshRenderer.material = meshMaterial;
    }

    // 在Inspector中更新顶点后实时预览
    void OnValidate()
    {
        if (Application.isPlaying)
        {
            CreateMeshFromPolygon();
        }
    }
}
```

