```csharp
using System.Collections.Generic;
using UnityEngine;

public static class Triangulator
{
    public static int[] Triangulate(Vector3[] points)
    {
        List<int> indices = new List<int>();

        int n = points.Length;
        if (n < 3)
            return indices.ToArray();

        List<int> vertexIndices = new List<int>(n);
        for (int i = 0; i < n; i++)
            vertexIndices.Add(i);

        int count = 0;
        while (n > 2)
        {
            bool earFound = false;
            for (int i = 0; i < n; i++)
            {
                int prev = (i == 0) ? n - 1 : i - 1;
                int next = (i + 1) % n;

                if (IsEar(points, vertexIndices, prev, i, next))
                {
                    indices.Add(vertexIndices[prev]);
                    indices.Add(vertexIndices[i]);
                    indices.Add(vertexIndices[next]);

                    vertexIndices.RemoveAt(i);
                    n--;
                    earFound = true;
                    break;
                }
            }

            if (!earFound)
            {
                // 防止无限循环，处理失败情况
                Debug.LogError("Triangulation failed.");
                break;
            }

            count++;
            if (count > 1000)
            {
                Debug.LogError("Exceeded iteration limit.");
                break;
            }
        }

        return indices.ToArray();
    }

    private static bool IsEar(Vector3[] points, List<int> vertexIndices, int prevIdx, int currIdx, int nextIdx)
    {
        Vector3 a = points[vertexIndices[prevIdx]];
        Vector3 b = points[vertexIndices[currIdx]];
        Vector3 c = points[vertexIndices[nextIdx]];

        // 检查是否为凸顶点
        if (!IsConvex(a, b, c))
            return false;

        // 检查其他顶点是否在三角形abc内
        for (int i = 0; i < vertexIndices.Count; i++)
        {
            if (i == prevIdx || i == currIdx || i == nextIdx)
                continue;
            Vector3 p = points[vertexIndices[i]];
            if (IsPointInTriangle(p, a, b, c))
                return false;
        }

        return true;
    }

    private static bool IsConvex(Vector3 a, Vector3 b, Vector3 c)
    {
        Vector3 cross = Vector3.Cross(b - a, c - b);
        return cross.z <= 0; // 假设在XY平面，顺时针为正方向
    }

    private static bool IsPointInTriangle(Vector3 p, Vector3 a, Vector3 b, Vector3 c)
    {
        // 使用重心坐标法判断点p是否在三角形abc内
        Vector3 v0 = c - a;
        Vector3 v1 = b - a;
        Vector3 v2 = p - a;

        float dot00 = Vector3.Dot(v0, v0);
        float dot01 = Vector3.Dot(v0, v1);
        float dot02 = Vector3.Dot(v0, v2);
        float dot11 = Vector3.Dot(v1, v1);
        float dot12 = Vector3.Dot(v1, v2);

        float invDenom = 1 / (dot00 * dot11 - dot01 * dot01);
        float u = (dot11 * dot02 - dot01 * dot12) * invDenom;
        float v = (dot00 * dot12 - dot01 * dot02) * invDenom;

        return (u >= 0) && (v >= 0) && (u + v < 1);
    }
}
```

