```csharp
using UnityEngine;
using UnityEngine.SceneManagement;
using System.Collections;

public class SceneTransition : MonoBehaviour
{
    [Header("过渡设置")]
    public float transitionDuration = 3.0f;
    public string sceneBName = "SceneB";
    public AnimationCurve movementCurve; // 运动速度曲线

    [Header("视觉效果")]
    public CanvasGroup fadeCanvas; // 淡入淡出UI
    public float fadeDuration = 1.0f;

    private Camera cameraA;
    private Camera cameraB;
    private bool isTransitioning = false;

    void Start()
    {
        cameraA = Camera.main;
        if (fadeCanvas != null)
            fadeCanvas.alpha = 0; // 初始化透明度
    }

    public void StartTransition()
    {
        if (!isTransitioning)
            StartCoroutine(TransitionCoroutine());
    }

    IEnumerator TransitionCoroutine()
    {
        isTransitioning = true;

        // 淡出当前场景
        if (fadeCanvas != null)
            yield return StartCoroutine(FadeCanvas(0, 1, fadeDuration));

        // 异步加载场景B
        AsyncOperation asyncLoad = SceneManager.LoadSceneAsync(sceneBName, LoadSceneMode.Additive);
        while (!asyncLoad.isDone)
            yield return null;

        // 查找场景B的相机
        Scene sceneB = SceneManager.GetSceneByName(sceneBName);
        GameObject[] sceneBObjects = sceneB.GetRootGameObjects();
        foreach (GameObject obj in sceneBObjects)
        {
            if (obj.CompareTag("MainCamera"))
            {
                cameraB = obj.GetComponent<Camera>();
                cameraB.enabled = false;
                break;
            }
        }

        if (cameraB == null)
        {
            Debug.LogError("未找到场景B的相机！");
            yield break;
        }

        // 记录起止点
        Vector3 startPos = cameraA.transform.position;
        Quaternion startRot = cameraA.transform.rotation;
        Vector3 endPos = cameraB.transform.position;
        Quaternion endRot = cameraB.transform.rotation;

        // 淡入新场景
        if (fadeCanvas != null)
            yield return StartCoroutine(FadeCanvas(1, 0, fadeDuration));

        // 平滑移动相机
        float elapsedTime = 0f;
        while (elapsedTime < transitionDuration)
        {
            float t = elapsedTime / transitionDuration;
            t = movementCurve.Evaluate(t); // 应用运动曲线
            cameraA.transform.position = Vector3.Lerp(startPos, endPos, t);
            cameraA.transform.rotation = Quaternion.Lerp(startRot, endRot, t);
            elapsedTime += Time.deltaTime;
            yield return null;
        }

        // 完成过渡
        cameraA.enabled = false;
        cameraB.enabled = true;
        SceneManager.UnloadSceneAsync(SceneManager.GetActiveScene());

        isTransitioning = false;
    }

    // 淡入淡出协程
    IEnumerator FadeCanvas(float startAlpha, float endAlpha, float duration)
    {
        float elapsedTime = 0f;
        while (elapsedTime < duration)
        {
            fadeCanvas.alpha = Mathf.Lerp(startAlpha, endAlpha, elapsedTime / duration);
            elapsedTime += Time.deltaTime;
            yield return null;
        }
        fadeCanvas.alpha = endAlpha;
    }
}
```

